#include "sim/simulation.hpp"
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <stdexcept>
using namespace scraperx::sim;
static void need(bool value,const char *why){if(!value)throw std::runtime_error(why);}
static void dump(const char *label,const Snapshot &p){
 std::cout<<std::setprecision(12)<<label<<" tick="<<p.tick_index<<" grounded="<<p.player_grounded
 <<" support="<<p.support_entity_id<<" commits="<<p.checkpoint_commit_count
 <<" P="<<p.player_position.x<<","<<p.player_position.y<<","<<p.player_position.z
 <<" V="<<p.player_linear_velocity.x<<","<<p.player_linear_velocity.y<<","<<p.player_linear_velocity.z
 <<" q="<<p.jib_hoist_position_meters<<" qdot="<<p.jib_hoist_velocity_mps
 <<" motorN="<<p.jib_hoist_motor_force_n<<" station="<<p.jib_station_active
 <<" deaths="<<p.death_count<<std::endl;
}
int main(){try{
 Simulation s(InitialSpawn::KernelJibStation,WorldContent::RegressionFixtures);
 double maxforce=0;
 auto one=[&](){
   need(s.advance_frame(Simulation::kFixedStepSeconds).accepted,"fixed tick refused");
   auto p=s.snapshot();
   need(std::isfinite(p.jib_hoist_position_meters)&&std::isfinite(p.jib_hoist_motor_force_n),"nonfinite hoist");
   maxforce=std::max(maxforce,std::abs(p.jib_hoist_motor_force_n));
   need(std::abs(p.jib_hoist_motor_force_n)<=20000.1,"20kN motor cap exceeded");
   need(p.death_count==0,"unexpected death");
   return p;
 };
 for(int i=0;i<45;++i)one();
 need(s.snapshot().player_grounded && s.snapshot().jib_station_active,"station lacks genuine ground");
 need(s.set_jib_hoist_input(1),"raise refused");
 for(int i=0;i<162;++i)one();
 need(s.set_jib_hoist_input(0),"neutral refused");
 for(int i=0;i<180;++i)one();
 auto a=s.snapshot();dump("SAVED_A",a);
 need(a.player_grounded && a.support_entity_id!=0,"A lacks actual footing");
 need(a.checkpoint_commit_count>0,"A not automatically committed");
 need(a.jib_hoist_position_meters>1 && a.jib_hoist_position_meters<2.8,"A not mid-extension");
 need(std::abs(a.jib_hoist_velocity_mps)<.02,"A not settled");
 need(s.request_jump(),"ordinary Jump refused");
 for(int i=0;i<11;++i){
   auto p=one();
   need(!p.player_grounded,"Jump did not establish actual flight");
   need(p.checkpoint_commit_count==a.checkpoint_commit_count,"Jump departure recommitted A");
 }
 dump("AIR_ESTABLISHED_BEFORE_RAISE",s.snapshot());
 need(s.set_jib_hoist_input(1),"air raise refused");
 for(int i=0;i<54;++i){
   auto p=one();
   need(!p.player_grounded,"intervening grounded tick invalidates frozen checkpoint");
   need(p.checkpoint_commit_count==a.checkpoint_commit_count,"airborne phase recommitted");
   need(p.jib_station_active,"airborne station departure invalidates raise");
   if(i%9==8)dump("AIR_RAISE",p);
 }
 need(s.set_jib_hoist_input(0),"air neutral refused");
 for(int i=0;i<9;++i){
   auto p=one();
   need(!p.player_grounded,"grounded before B latch");
   need(p.checkpoint_commit_count==a.checkpoint_commit_count,"B latch recommitted");
 }
 auto b=s.snapshot();dump("LATCHED_B",b);
 need(b.jib_hoist_position_meters-a.jib_hoist_position_meters>.35,"B insufficiently distinct from saved A");
 need(s.restart_checkpoint(),"checkpoint restart refused");
 auto r=s.snapshot();dump("RESTORED_A",r);
 need(r.checkpoint_commit_count==a.checkpoint_commit_count,"restart concealed a new checkpoint");
 need(std::abs(r.jib_hoist_position_meters-a.jib_hoist_position_meters)<.002,"restored body coordinate differs from A");
 double maxerror=0;
 for(int i=0;i<180;++i){
   auto p=one();
   maxerror=std::max(maxerror,std::abs(p.jib_hoist_position_meters-a.jib_hoist_position_meters));
   need(maxerror<.1,"neutral restored motor drifts outside A tolerance");
   if(i%45==44)dump("RESTORED_HOLD",p);
 }
 need(s.snapshot().player_grounded,"restore did not recover actual ground");
 std::cout<<"PASS ordinary-jump frozen-checkpoint Jib restore A="<<a.jib_hoist_position_meters
 <<" B="<<b.jib_hoist_position_meters<<" max_hold_error="<<maxerror
 <<" max_abs_motor_N="<<maxforce<<" frozen_commits="<<a.checkpoint_commit_count
 <<" airborne_ticks=74 deaths=0"<<std::endl;
 return 0;
 }catch(const std::exception &e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}}
